from format_lecon import D,paras
from medicaments_surface import q,zone,extrait
def akineton(l):
 s=(D/'evidence/AKINETON_24035_officiel.txt').read_text()
 dose=next(x for x in s.splitlines() if x.startswith('Troubles moteurs extrapyramidaux d’origine médicamenteuse ou autre: pour obtenir'))
 body=paras('Akineton injectable, n° Swissmedic 24035, contient du lactate de bipéridène, 5 mg dans une ampoule de 1 ml. L’indication suisse comprend les troubles extrapyramidaux médicamenteux ; le choix de la voie et la surveillance relèvent d’un professionnel.', 'Dose adulte injectable, citation AIPS :')+q(dose)+paras('Les comprimés ordinaires portent le n° 24036 et la forme retard le n° 54937 ; ils ne remplacent pas la solution injectable dans cette description. Cette dose individuelle ne se confond pas avec le maximum journalier. Une répétition n’est envisagée qu’après réévaluation ; absence de réponse, trouble de conscience ou atteinte respiratoire imposent de revoir simultanément le diagnostic et la sécurité.', 'Contre-indications, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Prudence devant tachycardie, convulsions, rétention urinaire ou troubles mentaux organiques. Surveiller état mental, pression artérielle, pouls, miction et symptômes oculaires ; la fiche demande le contrôle régulier de la pression intraoculaire.', 'Enfant : données limitées et formulations distinctes. Citations AIPS :')+zone(s,'\nEnfants et adolescents\n','\nChez les patients atteints')+paras('Ne pas extrapoler une dose adulte ni la forme retard à l’enfant. Les tranches d’âge ci-dessus sont celles de la fiche ; tout choix pédiatrique nécessite une validation médicale adaptée.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse/Allaitement\n','\nEffet sur')+paras('Interactions : addition des effets avec les autres anticholinergiques, majoration possible avec l’alcool et interactions avec plusieurs traitements neurologiques. Vérifier toute la prescription.', 'Avertissement concernant les formes tardives, citation AIPS :')+extrait(s,'Neuroleptiques: L’Akineton peut aggraver les dyskinésies tardives dues aux neuroleptiques.')+paras('Une dystonie aiguë et un syndrome tardif ne reçoivent donc pas automatiquement le même traitement. Les indications spécialisées de certaines dystonies ne suppriment pas cette précaution.', 'Arrêt du traitement oral, citation AIPS :')+zone(s,'\nMode d’utilisation\n','\nPour éviter')+paras('L’urgence peut imposer une conduite différente, décidée médicalement. Après une crise, organiser surveillance de récidive, révision du médicament causal et suivi ; ne pas laisser un anticholinergique prolongé sans réévaluation. La conduite et les machines peuvent être affectées par le médicament.')
 return l.subwindow('akineton','Akineton : traitement aigu et précautions',body,(25,26))
